// unai-game-day — which games are on this week, in San Antonio time.
// Plain ESM with JSDoc types, zero dependencies, no build step: Astro, Eleventy
// and plain Node all import it as-is. Schedule data lives in data/schedule.json
// and is regenerated by scripts/refresh.js from ESPN's public schedule.

/** @typedef {'nfl'|'nba'} League */
/** @typedef {'dal'|'hou'|'sa'} TeamKey */
/**
 * @typedef {Object} Game
 * @property {string} id         ESPN event id (shared when two tracked teams meet)
 * @property {League} league
 * @property {TeamKey[]} teams   tracked teams playing in this game
 * @property {string} home       home team short name, e.g. "Packers"
 * @property {string} away       away team short name, e.g. "Cowboys"
 * @property {string} start      kickoff, ISO 8601 UTC
 * @property {boolean} timeSet   false while the league has not fixed the kickoff time
 */

export const TIME_ZONE = 'America/Chicago';

/** @type {Record<TeamKey, {league: League, name: string, full: string}>} */
export const TEAMS = {
  dal: { league: 'nfl', name: 'Cowboys', full: 'Dallas Cowboys' },
  hou: { league: 'nfl', name: 'Texans', full: 'Houston Texans' },
  sa: { league: 'nba', name: 'Spurs', full: 'San Antonio Spurs' },
};

/** Minutes a game occupies the screens, kickoff to final whistle, with margin. */
export const DURATION_MIN = { nfl: 210, nba: 150 };

const DAY_MS = 86_400_000;

/** @param {Game} g */
export function endOf(g) {
  return new Date(Date.parse(g.start) + DURATION_MIN[g.league] * 60_000);
}

/** @param {Game} g @param {Date} [now] */
export function isLive(g, now = new Date()) {
  const t = now.getTime();
  return Date.parse(g.start) <= t && t < endOf(g).getTime();
}

/**
 * Games for the given teams that have not finished and kick off within `days`.
 * A game between two tracked teams appears once.
 * @param {{games: Game[]}} schedule
 * @param {{now?: Date, teams?: TeamKey[], days?: number, limit?: number}} [opts]
 * @returns {Game[]}
 */
export function upcomingGames(schedule, opts = {}) {
  const now = opts.now ?? new Date();
  const teams = opts.teams ?? /** @type {TeamKey[]} */ (Object.keys(TEAMS));
  const days = opts.days ?? 7;
  const horizon = now.getTime() + days * DAY_MS;
  const seen = new Set();
  const out = schedule.games
    .filter((g) => g.teams.some((t) => teams.includes(t)))
    .filter((g) => endOf(g).getTime() > now.getTime() && Date.parse(g.start) <= horizon)
    .filter((g) => (seen.has(g.id) ? false : (seen.add(g.id), true)))
    .sort((a, b) => Date.parse(a.start) - Date.parse(b.start));
  return opts.limit ? out.slice(0, opts.limit) : out;
}

/**
 * True while any tracked game is coming up. The page and the strip use this to
 * switch themselves off when the data runs out, so nothing outlives the season.
 * @param {{games: Game[]}} schedule
 * @param {{now?: Date, teams?: TeamKey[], days?: number}} [opts]
 */
export function isActive(schedule, opts = {}) {
  return upcomingGames(schedule, { ...opts, days: opts.days ?? 14 }).length > 0;
}

/**
 * Kickoff in Central time, split for display.
 * @param {Game} g
 * @param {'en'|'es'} [locale]
 * @returns {{weekday: string, date: string, time: string, timeSet: boolean}}
 */
export function kickoff(g, locale = 'en') {
  const tag = locale === 'es' ? 'es-MX' : 'en-US';
  const d = new Date(g.start);
  const part = (o) => new Intl.DateTimeFormat(tag, { timeZone: TIME_ZONE, ...o }).format(d);
  const weekday = part({ weekday: 'short' }).replace('.', '').toUpperCase();
  const date = part({ month: 'short', day: 'numeric' }).replace('.', '');
  const time = g.timeSet
    ? part({ hour: 'numeric', minute: '2-digit', hour12: true }).replace(/\s?a\.?\s?m\.?/i, ' AM').replace(/\s?p\.?\s?m\.?/i, ' PM').replace(/ /g, ' ')
    : locale === 'es' ? 'Hora por confirmar' : 'Time TBD';
  return { weekday, date, time, timeSet: g.timeSet };
}

/** "Cowboys @ Packers" — the broadcast convention, the same in both languages. @param {Game} g */
export function matchup(g) {
  return `${g.away} @ ${g.home}`;
}

/**
 * schema.org Event for watching the game at the venue. Throws without a venue
 * name and address: an Event with no location is invalid and Google drops it.
 * @param {Game} g
 * @param {{name: string, url: string, streetAddress: string, addressLocality: string, addressRegion: string, postalCode?: string}} venue
 * @param {'en'|'es'} [locale]
 */
export function eventJsonLd(g, venue, locale = 'en') {
  for (const k of ['name', 'url', 'streetAddress', 'addressLocality', 'addressRegion']) {
    if (!venue?.[k]) throw new Error(`eventJsonLd: venue.${k} is required`);
  }
  const title = locale === 'es' ? `${matchup(g)} — en ${venue.name}` : `${matchup(g)} — watch at ${venue.name}`;
  return {
    '@context': 'https://schema.org',
    '@type': 'Event',
    name: title,
    startDate: g.start,
    endDate: endOf(g).toISOString(),
    eventStatus: 'https://schema.org/EventScheduled',
    eventAttendanceMode: 'https://schema.org/OfflineEventAttendanceMode',
    isAccessibleForFree: true,
    location: {
      '@type': 'Restaurant',
      name: venue.name,
      url: venue.url,
      address: {
        '@type': 'PostalAddress',
        streetAddress: venue.streetAddress,
        addressLocality: venue.addressLocality,
        addressRegion: venue.addressRegion,
        ...(venue.postalCode ? { postalCode: venue.postalCode } : {}),
        addressCountry: 'US',
      },
    },
    organizer: { '@type': 'Organization', name: venue.name, url: venue.url },
  };
}
